using namespace std;
int main(){int n,m;cin>>n>>m;vector<pair<int,int>>edges(m);for(auto&e:edges)cin>>e.first>>e.second;vector<vector<int>>adj(n+1);vector<int>indeg(n+1,0);for(auto&e:edges){adj[e.first].push_back(e.second);indeg[e.second]++;}priority_queue<int,vector<int>,greater<int>>pq;for(int i2=1;i2<=n;i2++)if(indeg[i2]==0)pq.push(i2);vector<int>out;while(!pq.empty()){int u=pq.top();pq.pop();out.push_back(u);for(int v:adj[u]){if(--indeg[v]==0)pq.push(v);}}if((int)out.size()!=n)cout<<"-1\n";else{for(size_t i2=0;i2<out.size();i2++){if(i2)cout<<' ';cout<<out[i2];}cout<<"\n";}return 0;}

